package pose
import("testing";"os";"path/filepath";"strings")
func TestB38R5PreparedSemanticParity(t *testing.T){
 for _,kind:=range []string{"notes","version","fragment","policy"}{t.Run(kind,func(t *testing.T){r:=newReleaseRepo(t,"v1.0.0")
 switch kind {case "notes":r.notes="unrelated notes\n";r.manifest.NotesDigest=ReleaseDigest(r.notes);r.writeAll(t)
 case "version":relWrite(t,r.root,"VERSION","9.0.0\n")
 case "fragment":fs:=append([]ReleaseFragment{},r.manifest.Fragments...);fs[0].Body="different body";r.manifest=NewReleaseManifest(r.version,"",r.manifest.PreparedAt,fs,fixtureReleasePolicy(),ChangelogPolicy{},r.manifest.VersionEvidence);r.notes=RenderReleaseNotes(r.version,fs,ChangelogPolicy{});r.writeAll(t)
 case "policy":relWrite(t,r.root,".pose/policy/release.json",`{"schema_version":999}`)}
 s,e:=(Store{Root:r.root}).GetReleaseStatus(r.version);if e!=nil{t.Fatal(e)};if s.Releases[0].Sound(){t.Errorf("unsound %s candidate reported Sound: %+v",kind,s.Releases[0])}})}
}
func TestB38R5DanglingPoliciesAndFragments(t *testing.T){
 t.Run("policy",func(t *testing.T){r:=newReleaseRepo(t,"v1.0.0");os.Rename(filepath.Join(r.root,".pose/policy/release.json"),filepath.Join(r.root,".pose/release-policy.json"));os.Symlink("lost.json",filepath.Join(r.root,".pose/policy/release.json"));if p,e:=LoadReleasePolicy(r.root);e==nil{t.Errorf("lost primary policy fell back: %+v",p)}})
 t.Run("pending",func(t *testing.T){r:=newReleaseRepo(t,"v1.0.0");os.Symlink("lost",filepath.Join(r.root,".pose/changelogs/unreleased"));if fs,e:=LoadReleaseFragments(filepath.Join(r.root,".pose/changelogs/unreleased"),ChangelogPolicy{});e==nil{t.Errorf("lost pending read as empty: %+v",fs)}})
}
func TestB38R5ArchiveInvalidSnapshot(t *testing.T){r:=newReleaseRepo(t,"v1.0.0");relWrite(t,r.root,".pose/changelogs/v1.0.0.md","broken notes\n");r=tagged(t,r);snap:=snapshotOf(t,r);if snap.Intact(){t.Fatal("control should be invalid")};a:=LoadArchivedFragments(r.root);if len(a)==1&&a[0].Intact{t.Errorf("snapshot gaps %v but archival witness intact: %+v",snap.Gaps,a)}}
func TestB38R5WorktreeSymlinks(t *testing.T){r:=tagged(t,newReleaseRepo(t,"v1.0.0"));p:=filepath.Join(r.root,".pose/changelogs/v1.0.0/alpha.md");os.Rename(p,p+".real");os.Symlink("alpha.md.real",p);s,e:=(Store{Root:r.root}).GetReleaseStatus(r.version);if e!=nil{t.Fatal(e)};if s.Releases[0].Sound(){t.Error("symlink archive counted as sound")};a:=LoadArchivedFragments(r.root);if len(a)==1&&a[0].Intact{t.Error("symlink archive counted as intact")}}
func TestB38R5LossOfEmptyArchive(t *testing.T){r:=newReleaseRepo(t,"v1.0.0");r.manifest=NewReleaseManifest(r.version,"",r.manifest.PreparedAt,nil,fixtureReleasePolicy(),ChangelogPolicy{},r.manifest.VersionEvidence);r.notes=RenderReleaseNotes(r.version,nil,ChangelogPolicy{});r.writeAll(t);os.RemoveAll(filepath.Join(r.root,".pose/changelogs/v1.0.0"));os.Symlink("lost",filepath.Join(r.root,".pose/changelogs/v1.0.0"));if g:=ReleaseFilesGaps(r.root,r.version,&r.manifest);len(g)==0{t.Error("lost empty archive counted as present or absent")}}
func TestB38R5NumericPrecedence(t *testing.T){for _,p:=range [][2]string{{"v9.0.0","v10.0.0"},{"v1.0.0-rc.2","v1.0.0-rc.10"},{"v1.0.0-rc.10","v1.0.0"}}{if CompareReleasePrecedence(p[0],p[1])>=0{t.Error(p)}};_ = strings.Compare}
func TestB38R5DanglingAncestor(t *testing.T){root:=t.TempDir();os.Symlink("lost",filepath.Join(root,".pose"));s,e:=(Store{Root:root}).GetReleaseStatus("");if e==nil{t.Errorf("lost .pose returned empty complete status: %+v",s)}}
func TestB38R5AllHistoricalLoads(t *testing.T){root:="/home/go/.cache/pose-work/b38/pose-dist";es,e:=os.ReadDir(filepath.Join(root,".pose/releases"));if e!=nil{t.Fatal(e)};n:=0;for _,d:=range es{if !d.IsDir()||ValidateReleaseVersion(d.Name())!=nil{continue};n++;if _,e:=LoadReleaseManifest(root,d.Name());e!=nil{t.Error(e)}};t.Logf("historical manifests=%d",n)}
func TestB38R5DanglingEvents(t *testing.T){r:=tagged(t,newReleaseRepo(t,"v1.0.0"));os.Symlink("lost-events",filepath.Join(r.root,".pose/releases/v1.0.0/events.jsonl"));es,e:=LoadReleaseEvents(r.root,r.version);if e==nil{t.Errorf("lost event stream read as legitimately empty: %v",es)};s,e:=(Store{Root:r.root}).GetReleaseStatus(r.version);if e==nil&&s.Releases[0].Sound(){t.Error("lost event stream not disclosed by tagged status")}}
func TestB38R5LowNullKind(t *testing.T){m:=NewReleaseManifest("v1.0.0","","2026-10-02T00:00:00Z",nil,ReleasePolicy{SchemaVersion:1},ChangelogPolicy{},map[string]string{"source":EngineVersionFile,"kind":"","value":"v1.0.0"});b:=strings.Replace(string(CanonicalJSON(m)),`"kind": ""`,`"kind": null`,1);_,is:=ValidateReleaseManifestBytes([]byte(b),m.Version);if len(is)>0{t.Fatalf("probe changed: %v",is)};t.Log("kind:null is accepted as empty engine kind; exact engine source/value still required")}
func TestB38R5LowReadme(t *testing.T){r:=newReleaseRepo(t,"v1.0.0");relWrite(t,r.root,".pose/changelogs/v1.0.0/README.md","helper\n");fs,e:=LoadReleaseFragments(filepath.Join(r.root,".pose/changelogs/v1.0.0"),ChangelogPolicy{});if e!=nil||len(fs)!=1{t.Fatal(fs,e)};r=tagged(t,r);s:=snapshotOf(t,r);if !hasText(s.Gaps,"does not freeze"){t.Fatal(s.Gaps)};t.Log("loader ignores README; snapshot refuses it")}
func TestB38R5HistoricalSnapshotRendering(t *testing.T){root:="/home/go/.cache/pose-work/b38/pose-dist";for _,v:=range []string{"v1.1.0","v2.0.0"}{s,e:=ReadReleaseSnapshot(root,v);if e!=nil{t.Fatal(e)};policy,e:=changelogPolicyAt(root,s.Commit);if e!=nil{t.Fatal(e)};raw,e:=gitBlobAt(root,s.Commit,".pose/changelogs/"+v+".md");if e!=nil{t.Fatal(e)};want:=RenderReleaseNotes(v,s.Manifest.Fragments,policy);os.WriteFile("/tmp/b38r5-"+v+"-actual.md",raw,0644);os.WriteFile("/tmp/b38r5-"+v+"-rendered.md",[]byte(want),0644);if !s.Intact(){t.Errorf("historical tag %s refused: %v; notes digest still agrees=%v",v,s.Gaps,ReleaseDigest(string(raw))==s.Manifest.NotesDigest)}}}

