package cli
import("testing";"os";"path/filepath";"encoding/json";"bytes";posemodel "github.com/harne8/pose-mcp/internal/pose")
func TestB38R5PreparedStatusVsCheck(t *testing.T){
 for _,kind:=range []string{"notes","version","fragment","policy"}{t.Run(kind,func(t *testing.T){root:=cliReleaseRepo(t);p:=filepath.Join(root,".pose/releases/v1.0.0/manifest.json");raw,_:=os.ReadFile(p);var m posemodel.ReleaseManifest;json.Unmarshal(raw,&m)
 switch kind{case "notes":body:="unrelated notes\n";m.NotesDigest=posemodel.ReleaseDigest(body);os.WriteFile(p,posemodel.CanonicalJSON(m),0644);writeCloseoutCLIFile(t,root,".pose/changelogs/v1.0.0.md",body)
 case "version":writeCloseoutCLIFile(t,root,"VERSION","9.0.0\n")
 case "fragment":m.Fragments[0].Body="different body";m=posemodel.NewReleaseManifest(m.Version,m.PreviousVersion,m.PreparedAt,m.Fragments,cliFixturePolicy("text"),posemodel.ChangelogPolicy{},m.VersionEvidence);os.WriteFile(p,posemodel.CanonicalJSON(m),0644);writeCloseoutCLIFile(t,root,".pose/changelogs/v1.0.0.md",posemodel.RenderReleaseNotes(m.Version,m.Fragments,posemodel.ChangelogPolicy{}))
 case "policy":writeCloseoutCLIFile(t,root,".pose/policy/release.json",`{"schema_version":999}`)}
 gaps,_:=checkRelease(root,"v1.0.0");s,e:=(posemodel.Store{Root:root}).GetReleaseStatus("v1.0.0");if e!=nil{t.Fatal(e)};if len(gaps)==0{t.Fatal("check should refuse")};if s.Releases[0].Sound(){t.Errorf("check refuses %v; status/MCP returns Sound with gaps %v",gaps,s.Releases[0].Gaps)}})}
}
func TestB38R5PendingLossPassesCheck(t *testing.T){root:=cliReleaseRepo(t);os.Symlink("lost",filepath.Join(root,".pose/changelogs/unreleased"));if g,_:=checkRelease(root,"v1.0.0");len(g)==0{t.Error("valid check despite lost pending inventory")}}
func TestB38R5PolicyLossPassesCheck(t *testing.T){root:=cliReleaseRepo(t);os.Rename(filepath.Join(root,".pose/policy/release.json"),filepath.Join(root,".pose/release-policy.json"));os.Symlink("lost",filepath.Join(root,".pose/policy/release.json"));if g,_:=checkRelease(root,"v1.0.0");len(g)==0{t.Error("valid check despite lost primary policy")}}
func TestB38R5PrepareOverwritesDanglingManifest(t *testing.T){root,target:=preparedEngineReleaseWith(t,true);p:=filepath.Join(root,".pose/releases",target,"manifest.json");os.Remove(p);os.RemoveAll(filepath.Join(root,".pose/changelogs",target));os.Symlink("lost.json",p);var out,errOut bytes.Buffer;code:=cmdReleasePrepare(root,[]string{"--version",target,"--apply"},&out,&errOut);_,err:=os.Stat(filepath.Join(filepath.Dir(p),"lost.json"));if code==0&&err==nil{t.Errorf("prepare wrote through a lost manifest link: %s %s",out.String(),errOut.String())}}

func TestB38R5ChangelogContractParity(t *testing.T){for _,raw:=range []string{`{"schema_version":999}`,`{broken`}{t.Run(raw,func(t *testing.T){root:=cliReleaseRepo(t);writeCloseoutCLIFile(t,root,".pose/policy/changelog.json",raw);g,_:=checkRelease(root,"v1.0.0");if len(g)==0{t.Errorf("prepared check accepts unreadable/unsupported changelog policy: %s",raw)};relGitCLI(t,root,"add","-A");relGitCLI(t,root,"commit","-q","-m","policy");relGitCLI(t,root,"tag","v1.0.0");snap,e:=posemodel.ReadReleaseSnapshot(root,"v1.0.0");if e!=nil||snap.Intact(){t.Fatalf("snapshot should refuse: %+v %v",snap,e)};t.Logf("snapshot correctly refuses %v",snap.Gaps)})}}
func TestB38R5CheckerPendingError(t *testing.T){root:=cliReleaseRepo(t);writeCloseoutCLIFile(t,root,".pose/policy/release.json",`{"schema_version":1,"adopted_at":"2026-10-01","provider":"github","repository":"o/r","version_source":{"path":"VERSION","kind":"text"}}`);writeCloseoutCLIFile(t,root,".pose/changelogs/unreleased/bad.md","malformed\n");c:=nativeChecker{root:root,mode:"strict",stdout:&bytes.Buffer{}};appendReleasePolicyChecks(&c);t.Logf("checker=%+v",c);if c.errors==0{t.Error("pending parse error silently discarded by release subchecker")}}
func TestB38R5CheckerPendingLoss(t *testing.T){root:=cliReleaseRepo(t);writeCloseoutCLIFile(t,root,".pose/policy/release.json",`{"schema_version":1,"adopted_at":"2026-10-01","provider":"github","repository":"o/r","version_source":{"path":"VERSION","kind":"text"}}`);os.Symlink("lost",filepath.Join(root,".pose/changelogs/unreleased"));c:=nativeChecker{root:root,mode:"strict",stdout:&bytes.Buffer{}};appendReleasePolicyChecks(&c);c.checkChangelogs();if c.errors==0{t.Error("both release and changelog subchecks fail to report dangling pending inventory")}}
func TestB38R5CheckerWorktreeParity(t *testing.T){for _,tagged:=range []bool{false,true}{root:=cliReleaseRepo(t);p:=filepath.Join(root,".pose/releases/v1.0.0/manifest.json");raw,_:=os.ReadFile(p);var m posemodel.ReleaseManifest;json.Unmarshal(raw,&m);policy:=cliFixturePolicy("text");policy.AdoptedAt="2026-10-01";policy.Provider="github";policy.Repository="o/r";m=posemodel.NewReleaseManifest(m.Version,m.PreviousVersion,m.PreparedAt,m.Fragments,policy,posemodel.ChangelogPolicy{},m.VersionEvidence);writeCloseoutCLIFile(t,root,".pose/policy/release.json",string(posemodel.CanonicalJSON(policy)));os.WriteFile(p,posemodel.CanonicalJSON(m),0644);relGitCLI(t,root,"add","-A");relGitCLI(t,root,"commit","-q","-m","adopt");if tagged{relGitCLI(t,root,"tag","v1.0.0")};writeCloseoutCLIFile(t,root,".pose/changelogs/v1.0.0.md","wrong notes\n");g,_:=checkRelease(root,"v1.0.0");if len(g)==0{t.Fatal("control release check should refuse")};c:=nativeChecker{root:root,mode:"strict",stdout:&bytes.Buffer{}};appendReleasePolicyChecks(&c);if c.errors==0{t.Errorf("tagged=%v: release subchecker accepted worktree refused by check: %v",tagged,g)}}}
func TestB38R5LowHumanLimits(t *testing.T){root:=cliReleaseRepoKind(t,"engine");relGitCLI(t,root,"tag","v1.0.0");snap,e:=posemodel.ReadReleaseSnapshot(root,"v1.0.0");if e!=nil||len(snap.Limits)==0{t.Fatal(snap,e)};var out,errOut bytes.Buffer;code:=cmdReleaseStatus(root,nil,&out,&errOut);if code!=0{t.Fatal(errOut.String())};t.Logf("human status omits engine re-read limit: %s",out.String())}
